/*
 * Built for Kinetic from scratch after the public preview of BoardUI's "Stacked Card Fan" (boardui.com/).
 * No BoardUI source was used.
 */
"use client";

import { useRef, useState } from "react";
import type { CSSProperties, KeyboardEvent, ReactNode } from "react";
import { RiCollapseDiagonalLine, RiExpandDiagonalLine } from "@remixicon/react";
import { mergeProps, useFocusRing, useHover } from "react-aria";
import { Button } from "@/components/motion/button";
import { cx } from "@/lib/cx";
import { useResizeObserver } from "@/hooks/use-resize-observer";

export interface StackedCardFanItem {
  id: string;
  /** Announced when the card comes to the front. */
  label: string;
  content: ReactNode;
}

export interface StackedCardFanProps {
  items: StackedCardFanItem[];
  activeIndex?: number;
  defaultActiveIndex?: number;
  onActiveChange?: (index: number) => void;
  expanded?: boolean;
  defaultExpanded?: boolean;
  onExpandedChange?: (expanded: boolean) => void;
  /** Show the "See all" pill under the stack. */
  showToggle?: boolean;
  expandLabel?: string;
  collapseLabel?: string;
  /** Card size in px; both shrink together when the container is narrow. */
  cardWidth?: number;
  cardHeight?: number;
  /** Fade the lower part of the stack into the page. */
  fade?: boolean;
  "aria-label"?: string;
  className?: string;
}

type FanVars = CSSProperties & Record<`--${string}`, string | number>;

// #region critical
/**
 * Signed circular distance from the front card: for five cards and front 0,
 * the order is 0, 1, 2, -2, -1. The front card sits at 0, the rest alternate
 * to its right (+) and left (-), and cycling the front card makes the one
 * leaving the far end slip round behind the stack to the other end.
 */
function slotOf(index: number, active: number, count: number) {
  const half = Math.floor(count / 2);
  return ((((index - active + half) % count) + count) % count) - half;
}

/**
 * Every card has one transform made of CSS variables: `--d` (its slot) and
 * `--ad` (|slot|) are set per card, while `--spread`, `--tilt`, `--drop`,
 * `--shrink` are set by the stack state (rest, peek on hover/focus, expanded). A change of
 * either re-computes the transform and a single CSS transition animates it, so
 * hover, cycling and expanding all share one code path with no JS animation.
 * The horizontal gap is capped by the container so the outer cards never
 * leave it: half * gap + card / 2 <= 50cqi.
 */
const CARD_TRANSFORM =
  "translateX(-50%) translateX(calc(var(--d) * var(--gap))) translateY(calc(var(--ad) * var(--drop))) rotate(calc(var(--d) * var(--tilt))) scale(calc(var(--base) * (1 - var(--ad) * var(--shrink))))";

const GAP = "max(12px, min(calc(var(--card-w) * var(--spread)), calc((100cqi - var(--card-w)) / var(--span))))";

/** Each expanded card advances this fraction of a card width past the one before (14% overlap). */
const EXPANDED_STEP = 0.86;

/**
 * Expanded lays every card out in a row, so cards must also shrink: the scale
 * that makes card + (n - 1) * step * card fit the measured width. Scale is a
 * plain number, which CSS cannot derive from lengths everywhere yet, so it is
 * computed here from the container's layout width.
 */
function expandedLayout(width: number, cardWidth: number, count: number) {
  const card = Math.min(cardWidth, width * 0.8);
  const scale = Math.min(1, width / (card * (1 + (count - 1) * EXPANDED_STEP)));
  return { scale, gap: card * scale * EXPANDED_STEP };
}
// #endregion

/**
 * A fanned stack of cards. Hovering or focusing it spreads the fan; clicking
 * the front card or pressing the arrow keys brings the next card forward, and
 * clicking a card behind brings that one forward.
 */
export function StackedCardFan({
  items,
  activeIndex,
  defaultActiveIndex = 0,
  onActiveChange,
  expanded,
  defaultExpanded = false,
  onExpandedChange,
  showToggle = true,
  expandLabel,
  collapseLabel = "Stack cards",
  cardWidth = 300,
  cardHeight = 260,
  fade = false,
  "aria-label": ariaLabel = "Card stack",
  className,
}: StackedCardFanProps) {
  const count = items.length;
  const [innerActive, setInnerActive] = useState(defaultActiveIndex);
  const [innerExpanded, setInnerExpanded] = useState(defaultExpanded);
  const active = count ? (((activeIndex ?? innerActive) % count) + count) % count : 0;
  const isExpanded = expanded ?? innerExpanded;
  const { hoverProps, isHovered } = useHover({});
  const { focusProps, isFocusVisible } = useFocusRing();
  const wrapRef = useRef<HTMLDivElement>(null);
  const { width } = useResizeObserver(wrapRef);

  const select = (index: number) => {
    const next = ((index % count) + count) % count;
    if (activeIndex === undefined) setInnerActive(next);
    onActiveChange?.(next);
  };
  const toggle = () => {
    if (expanded === undefined) setInnerExpanded(!isExpanded);
    onExpandedChange?.(!isExpanded);
  };

  const onKeyDown = (event: KeyboardEvent) => {
    const step: Record<string, number> = { ArrowRight: 1, ArrowDown: 1, ArrowLeft: -1, ArrowUp: -1, Enter: 1, " ": 1 };
    if (event.key === "Home") select(0);
    else if (event.key === "End") select(count - 1);
    else if (step[event.key] !== undefined) select(active + step[event.key]!);
    else return;
    event.preventDefault();
  };

  const state = isExpanded ? "expanded" : isHovered || isFocusVisible ? "peek" : "rest";
  const front = items[active];
  const vars: FanVars = {
    "--card-w": `min(${cardWidth}px, 80cqi)`,
    "--card-h": `calc(var(--card-w) * ${cardHeight / cardWidth})`,
    "--span": Math.max(1, 2 * Math.floor(count / 2)),
  };
  // --gap reads --spread, which the stage sets per state, so it is declared on the stage.
  const stageVars: FanVars = { height: "calc(var(--card-h) + 64px)", "--gap": GAP, "--base": 1 };
  if (isExpanded && width > 0) {
    const layout = expandedLayout(width, cardWidth, count);
    stageVars["--gap"] = `${layout.gap}px`;
    stageVars["--base"] = layout.scale;
  }

  return (
    <div ref={wrapRef} className={cx("@container/fan flex w-full flex-col items-center", className)} style={vars}>
      <div
        {...mergeProps(hoverProps, focusProps)}
        role="group"
        aria-roledescription="card stack"
        aria-label={`${ariaLabel}. Use the arrow keys to bring the next card forward.`}
        tabIndex={0}
        onKeyDown={onKeyDown}
        data-state={state}
        data-active={active}
        className={cx(
          "relative w-full rounded-3xl outline-none",
          "[--drop:10px] [--shrink:0.04] [--spread:0.3] [--tilt:5deg]",
          "data-[state=peek]:[--drop:16px] data-[state=peek]:[--spread:0.46] data-[state=peek]:[--tilt:8deg]",
          "data-[state=expanded]:[--drop:4px] data-[state=expanded]:[--shrink:0] data-[state=expanded]:[--spread:0.98] data-[state=expanded]:[--tilt:1.5deg]",
          "focus-visible:ring-2 focus-visible:ring-accent-500 focus-visible:ring-offset-4 focus-visible:ring-offset-background-primary-default",
          fade && "mask-b-from-55% mask-b-to-100%",
        )}
        style={stageVars}
      >
        {items.map((item, index) => {
          const d = slotOf(index, active, count);
          const ad = Math.abs(d);
          const isFront = d === 0;
          return (
            <div
              key={item.id}
              aria-hidden={isFront ? undefined : true}
              data-front={isFront || undefined}
              data-card={item.id}
              onClick={() => select(isFront ? active + 1 : index)}
              className={cx(
                "@container/card absolute top-4 left-1/2 flex cursor-pointer flex-col overflow-hidden rounded-[22px] border border-border-button-default bg-background-primary-default p-4 shadow-lg select-none",
                "transition-transform duration-500 ease-[cubic-bezier(0.22,1,0.36,1)] motion-reduce:transition-none",
              )}
              style={{
                width: "var(--card-w)",
                height: "var(--card-h)",
                zIndex: count - ad,
                transform: CARD_TRANSFORM,
                ["--d" as string]: d,
                ["--ad" as string]: ad,
              }}
            >
              {item.content}
              <span
                aria-hidden="true"
                className="pointer-events-none absolute inset-0 bg-background-primary-default transition-opacity duration-500 motion-reduce:transition-none"
                style={{ opacity: Math.min(0.6, ad * (isExpanded ? 0.08 : 0.24)) }}
              />
            </div>
          );
        })}
      </div>

      <span className="sr-only" aria-live="polite">
        {front ? `${front.label}, ${active + 1} of ${count}` : ""}
      </span>

      {showToggle && count > 1 ? (
        <Button
          variant="secondary"
          size="small"
          leadingIcon={isExpanded ? RiCollapseDiagonalLine : RiExpandDiagonalLine}
          type="button"
          aria-pressed={isExpanded}
          onClick={toggle}
          className="relative z-10 -mt-5 rounded-full shadow-sm"
        >
          {isExpanded ? collapseLabel : (expandLabel ?? `See all ${count}`)}
        </Button>
      ) : null}
    </div>
  );
}

/*
 * Built for Kinetic from scratch after the public preview of BoardUI's "Stacked Card Fan" (boardui.com/).
 * No BoardUI source was used.
 */
"use client";

import { useId } from "react";
import { RiArrowLeftSLine, RiArrowRightSLine, RiCheckboxBlankCircleLine, RiLoader4Line } from "@remixicon/react";
import { Chip } from "@/components/motion/chip";
import type { StackedCardFanItem } from "@/components/motion/stacked-card-fan";

/*
 * Five agent-dashboard card faces sized for StackedCardFan (they fill the card
 * and lay out with flex, so they work from about 230 to 320px wide). They are
 * pictures of an app: static, with no focusable content.
 */

function Meter({ label, value, tone = "bg-chart-6" }: { label: string; value: number; tone?: string }) {
  return (
    <div className="flex flex-col gap-1.5">
      <div className="flex items-center justify-between gap-2 text-caption-1-medium">
        <span className="truncate text-text-secondary">{label}</span>
        <span className="text-text-tertiary tabular-nums">{value}%</span>
      </div>
      <span className="h-1.5 overflow-hidden rounded-full bg-background-tertiary-default">
        <span className={`block h-full rounded-full ${tone}`} style={{ width: `${value}%` }} />
      </span>
    </div>
  );
}

export function UsageCardFace() {
  return (
    <div className="flex h-full flex-col gap-4">
      <div className="flex flex-col gap-2">
        <span className="text-body-semibold text-text-primary">Context window</span>
        <Meter label="Used this session" value={62} />
      </div>
      <span className="h-px bg-separator-border" />
      <div className="flex flex-col gap-3">
        <span className="text-body-semibold text-text-primary">Plan usage</span>
        <Meter label="5-hour limit" value={48} />
        <Meter label="Weekly, all models" value={22} />
        <Meter label="Weekly, large model" value={9} tone="bg-chart-5" />
      </div>
    </div>
  );
}

const STEPS = ["Read the brief", "Update the schema", "Implement the endpoint", "Add tests", "Run checks"];

export function StepsCardFace() {
  return (
    <div className="flex h-full flex-col gap-3">
      <div className="flex items-center gap-2">
        <RiLoader4Line className="size-4 animate-spin text-accent-500 motion-reduce:animate-none" aria-hidden="true" />
        <span className="text-body-semibold text-text-primary">5 steps left</span>
      </div>
      <ul className="flex flex-col gap-1">
        {STEPS.map((step, i) => (
          <li
            key={step}
            className={`flex items-center gap-2.5 rounded-xl px-2.5 py-2 text-body-medium ${
              i === 0 ? "border border-border-button-default bg-background-secondary-default text-text-primary" : "text-text-tertiary"
            }`}
          >
            {i === 0 ? (
              <RiLoader4Line className="size-4 shrink-0 animate-spin text-text-secondary motion-reduce:animate-none" aria-hidden="true" />
            ) : (
              <RiCheckboxBlankCircleLine className="size-4 shrink-0 text-foreground-icon-tertiary" aria-hidden="true" />
            )}
            <span className="truncate">{step}</span>
          </li>
        ))}
      </ul>
    </div>
  );
}

const TOKENS = [58, 46, 16, 4, 4, 4, 4, 4, 4, 70, 18, 12, 10, 20, 10, 8, 86, 96, 92, 66, 18, 8, 34, 44, 62, 50, 42];
const W = 300;
const H = 120;
const tokenPoints = TOKENS.map((v, i) => [(i / (TOKENS.length - 1)) * W, H - (v / 100) * (H - 8)] as const);
const tokenLine = tokenPoints.map(([x, y], i) => `${i ? "L" : "M"}${x.toFixed(1)} ${y.toFixed(1)}`).join(" ");
const tokenArea = `${tokenLine} L${W} ${H} L0 ${H} Z`;

export function TokensCardFace() {
  const gradient = useId();
  return (
    <div className="flex h-full flex-col">
      <span className="text-caption-1-medium text-text-secondary">Tokens</span>
      <div className="mt-1 flex items-center gap-2">
        <span className="min-w-0 truncate text-title-3-semibold text-text-primary tabular-nums">
          667.7M<span className="hidden @3xs/card:inline"> tokens</span>
        </span>
        <Chip variant="subtle" color="purple">
          +9.4%
        </Chip>
      </div>
      <svg viewBox={`0 0 ${W} ${H}`} preserveAspectRatio="none" className="mt-3 min-h-0 w-full flex-1 text-chart-5" aria-hidden="true">
        <defs>
          <linearGradient id={gradient} x1="0" x2="0" y1="0" y2="1">
            <stop offset="0" stopColor="currentColor" stopOpacity="0.28" />
            <stop offset="1" stopColor="currentColor" stopOpacity="0" />
          </linearGradient>
        </defs>
        <path d={tokenArea} fill={`url(#${gradient})`} />
        <path d={tokenLine} fill="none" stroke="currentColor" strokeWidth="2" strokeLinejoin="round" vectorEffect="non-scaling-stroke" />
      </svg>
      <div className="mt-2 flex justify-between text-caption-2-regular text-text-tertiary">
        <span>Jun 14</span>
        <span>Today</span>
      </div>
    </div>
  );
}

const HEAT = [0, 1, 2, 1, 0, 3, 2, 1, 2, 3, 3, 1, 0, 1, 2, 3, 2, 2, 1, 0, 3, 3, 2, 1, 2, 1, 0, 2, 3, 1];
const HEAT_TONE = ["bg-background-tertiary-default", "bg-chart-5/25", "bg-chart-5/55", "bg-chart-5"];

export function CalendarCardFace() {
  return (
    <div className="flex h-full flex-col gap-3">
      <div className="flex items-center justify-between gap-2">
        <span className="text-body-semibold text-text-primary">September</span>
        <span className="flex gap-1 text-foreground-icon-secondary" aria-hidden="true">
          <RiArrowLeftSLine className="size-4" />
          <RiArrowRightSLine className="size-4" />
        </span>
      </div>
      <div className="grid grid-cols-7 gap-1 text-center text-caption-2-medium text-text-tertiary">
        {["M", "T", "W", "T", "F", "S", "S"].map((d, i) => (
          <span key={i}>{d}</span>
        ))}
      </div>
      <div className="grid min-h-0 flex-1 grid-cols-7 grid-rows-5 gap-1">
        {HEAT.map((level, i) => (
          <span key={i} className={`rounded-[5px] ${HEAT_TONE[level] ?? HEAT_TONE[0]}`} />
        ))}
      </div>
    </div>
  );
}

const REQUESTS = [22, 30, 26, 44, 38, 52, 34, 60, 48, 70, 56, 64, 82, 58, 76, 90, 68, 84, 96, 72, 88, 80, 94, 100];

export function RequestsCardFace() {
  return (
    <div className="flex h-full flex-col">
      <span className="text-caption-1-medium text-text-secondary">Requests</span>
      <span className="mt-1 text-title-3-semibold text-text-primary tabular-nums">18.2k</span>
      <div className="mt-3 flex min-h-0 flex-1 items-end gap-[3px]" aria-hidden="true">
        {REQUESTS.map((v, i) => (
          <span key={i} className={`flex-1 rounded-full ${i % 3 === 2 ? "bg-chart-9" : "bg-chart-5"}`} style={{ height: `${v}%` }} />
        ))}
      </div>
      <div className="mt-3 flex items-center gap-3 text-caption-2-medium text-text-tertiary">
        <span className="flex items-center gap-1.5">
          <span className="size-2 rounded-full bg-chart-5" />
          Chat
        </span>
        <span className="flex items-center gap-1.5">
          <span className="size-2 rounded-full bg-chart-9" />
          Agents
        </span>
      </div>
    </div>
  );
}

/** The five faces in fan order, ready for `<StackedCardFan items={…} />`. Front card is index 0. */
export const AGENT_DASHBOARD_CARDS: StackedCardFanItem[] = [
  { id: "tokens", label: "Tokens", content: <TokensCardFace /> },
  { id: "calendar", label: "September activity", content: <CalendarCardFace /> },
  { id: "requests", label: "Requests", content: <RequestsCardFace /> },
  { id: "usage", label: "Context window and plan usage", content: <UsageCardFace /> },
  { id: "steps", label: "5 steps left", content: <StepsCardFace /> },
];
